{"updateComponents":{"surfaceId":"event-form","components":[{"id":"root","component":"Card","title":"New event","description":"Schedule a calendar event and invite attendees.","children":["form"],"style":{"maxWidth":"640px","width":"100%","marginHorizontal":"auto"}},{"id":"form","component":"Form","name":"createEvent","children":["title","dates","times","attendees","description","reminder","actions"],"on":{"submit":{"event":{"name":"saveEvent","context":{"title":{"path":"/event/title"},"startDate":{"path":"/event/startDate"},"endDate":{"path":"/event/endDate"},"startTime":{"path":"/event/startTime"},"endTime":{"path":"/event/endTime"},"attendees":{"path":"/event/attendees"},"description":{"path":"/event/description"},"reminder":{"path":"/event/reminder"}}}}}},{"id":"title","component":"Input","label":"Title","name":"title","placeholder":"e.g. Quarterly planning","value":{"path":"/event/title"},"checks":[{"condition":{"call":"required","args":{"value":{"path":"/event/title"}}},"message":"Enter a title"}]},{"id":"dates","component":"DateRangePicker","label":"Dates","name":"dates","start":{"path":"/event/startDate"},"end":{"path":"/event/endDate"}},{"id":"times","component":"Grid","columns":{"base":1,"sm":2},"gap":"md","children":["startTime","endTime"]},{"id":"startTime","component":"TimePicker","label":"Start time","name":"startTime","value":{"path":"/event/startTime"},"step":15},{"id":"endTime","component":"TimePicker","label":"End time","name":"endTime","value":{"path":"/event/endTime"},"step":15},{"id":"attendees","component":"ChipInput","label":"Attendees","name":"attendees","placeholder":"Add a name or email","values":{"path":"/event/attendees"},"suggestions":{"path":"/suggestions"}},{"id":"description","component":"Textarea","label":"Description","name":"description","placeholder":"Agenda, links, notes…","rows":4,"autosize":true,"maxRows":10,"value":{"path":"/event/description"}},{"id":"reminder","component":"Switch","label":"Reminder","name":"reminder","description":"Notify attendees 15 minutes before the event","checked":{"path":"/event/reminder"}},{"id":"actions","component":"Stack","direction":"horizontal","gap":"sm","justify":"end","children":["cancelBtn","saveBtn"]},{"id":"cancelBtn","component":"Button","label":"Cancel","variant":"ghost","on":{"press":{"event":{"name":"cancelEvent"}}}},{"id":"saveBtn","component":"Button","label":"Save","icon":"check","submit":true}]}}
